content.data:
terraform {
  backend "s3" {}
}

locals {
  # Generate log group names from DMS task IDs
  dms_log_groups = [
    for id in var.dms_task_ids : "dms-serverless-replication-${id}"
  ]

  # Filter by pattern if provided
  filtered_log_groups = var.log_group_pattern != "" ? [
    for lg in local.dms_log_groups : lg
    if can(regex(var.log_group_pattern, lg))
  ] : local.dms_log_groups
  all_log_groups = local.dms_log_groups
}

# Create subscription filter for each DMS log group
resource "aws_cloudwatch_log_subscription_filter" "dms_task_logs" {
  for_each = toset(local.filtered_log_groups)

  name            = "${var.environment}-${each.value}-to-splunk"
  log_group_name  = each.value
  filter_pattern  = ""
  destination_arn = var.firehose_delivery_stream_arn
  role_arn        = var.subscription_filter_role_arn
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "ap-southeast-2"
}

variable "project" {
  description = "Project name"
  type        = string
  default     = "onedata"
}

variable "cost_centre" {
  description = "Cost centre for billing"
  type        = string
  default     = "onedata"
}

variable "environment" {
  description = "Environment name (dev, tst, pst, prd)"
  type        = string
}

variable "dms_task_ids" {
  description = "List of DMS task unique IDs (e.g., ['WHVFP5XJKJFKTHVUQN5A3VKN6Y'])"
  type        = list(string)
}

variable "log_group_pattern" {
  description = "Optional regex pattern to filter log groups (e.g., '.*onedata-projects.*'). Leave empty to include all groups."
  type        = string
  default     = ""
}

variable "firehose_delivery_stream_arn" {
  description = "ARN of the Firehose delivery stream created by Splunk team"
  type        = string
}

variable "subscription_filter_role_arn" {
  description = "ARN of the IAM role for CloudWatch Logs subscription filter"
  type        = string
}

include "root" {
  path = find_in_parent_folders()
}

terraform {
  source = "../../.."
}

remote_state {
  backend = "s3"
  config = {
    bucket               = "remote-tfstate-ap-southeast-2-597924334156"
    key                  = "infrastructure/dms-cw-subscription-filters/digitalprd/prd/terraform.tfstate"
    region               = "ap-southeast-2"
    workspace_key_prefix = "onedata"

    skip_bucket_versioning              = true
    skip_bucket_ssencryption           = true
    skip_bucket_public_access_blocking = true
    skip_bucket_root_access            = true
  }
}

inputs = {
  environment                      = "prd"
  dms_task_ids                     = ["PZ74ZXGMS5FIPNGOEAOWJGVPXA"]
  log_group_pattern                = ""
  firehose_delivery_stream_arn     = "arn:aws:firehose:ap-southeast-2:597924334156:deliverystream/prd-onedata-projects-firehose-delivery-stream"  
  subscription_filter_role_arn     = "arn:aws:iam::597924334156:role/prd-onedata-projects-CWLogsSubFilterIAMRole"
}

